If.CustomBehavior:
System.Threading.Tasks.Task.Run(async () =>
{
    int questId = 9361;
    int itemToUse = 23268;
    int itemToWatch = 23270;

    while (true)
    {
        if (!Quest.HasQuest(questId))
            break;

        var bagItems = wManager.Wow.Helpers.Bag.GetBagItem();
        bool foundWatchItem = false;

        for (int i = 0; i < bagItems.Count; i++)
        {
            if (bagItems[i].Entry == itemToWatch)
            {
                foundWatchItem = true;
                break;
            }
        }

        if (foundWatchItem)
        {
            for (int i = 0; i < bagItems.Count; i++)
            {
                if (bagItems[i].Entry == itemToUse)
                {
                    UseItem(bagItems[i].Name);
                    await Coroutine.Sleep(2000); // подождать после использования
                    break;
                }
            }
        }

        await Coroutine.Sleep(1000);
    }
});

