       if (Me.CurrentTarget.IsValid && Me.CurrentTarget.IsAlive && Me.CurrentTarget.HealthPercent <= 99)
       {
Me.ClearTarget();   
UseItem(itemId);
await Coroutine.Sleep(5000);
     wManager.wManagerSetting.CurrentSetting.ListHarvest.Add(1);   
       }
      }
      await Coroutine.Sleep(5000);
     }
    });
    

